    this.skinWidth = 0.02,
    this.maxSlope = 0.7853982,
    this.maxStepHeight = 0.3,
    this.snapToGround = 0.2,
    this.gravityScale = 1.0,
    this.mass = 70.0,
    this.speed = 4.0,
    this.jumpSpeed = 5.0,
    this.turnSpeed = 10.0,
    this.moveAction = '',
    this.jumpAction = '',
    this.mask = 4294967295,
  });

  /// Capsule radius, metres, `> 0`.
  final double radius;
  /// Total capsule height (both caps included), `>= 2 * radius`.
  final double height;
  /// The capsule's centre in the entity's local frame (scaled by the entity's scale, like a collider offset).
  final Vec3 center;
  /// Skin the controller keeps from geometry, metres, `>= 0`.
  final double skinWidth;
  /// Steepest climbable slope, radians in `0..pi/2`; steeper ground slides the character down.
  final double maxSlope;
  /// Highest step climbed without a jump, metres (`0` disables).
  final double maxStepHeight;
  /// How far below the feet ground still counts as touched when walking off a bump, metres (`0` disables).
  final double snapToGround;
  /// Multiplies the world's gravity; `0` is a flying character whose `move` velocity is used in full (vertical included).
