    d.setFloat32(offset + 40, mass, Endian.little);
    d.setFloat32(offset + 44, speed, Endian.little);
    d.setFloat32(offset + 48, jumpSpeed, Endian.little);
    d.setFloat32(offset + 52, turnSpeed, Endian.little);
    writeWireString(d, offset + 56, moveAction, strings);
    writeWireString(d, offset + 64, jumpAction, strings);
