      other is ProjectionAnchorRecord && other.entity == entity && other.offset == offset && other.mask == mask;

  @override
  int get hashCode => Object.hashAll([entity, offset, mask]);

  @override
  String toString() => 'ProjectionAnchorRecord(entity: $entity, offset: $offset, mask: $mask)';
}

