/// Plays one clip over the entity's subtree (M3-19, `docs/animation.md`): every channel of `clip` drives the first descendant (the entity itself included) named like the channel's target, in the pre-tick slot, so physics and the catalogue see the posed transforms this tick. `speed` scales time (negative plays backwards); a `looping` clip wraps, one that is not stops at its last key with `playing` cleared and an `ANIMATION_ENDED` event. `Command::Animate` plays, crossfades, stops, pauses, resumes, re-speeds and seeks it from Dart; the world must know the clip (`World::register_clip`; the loaders register every clip a loaded scene's animators name, `CLIP_UNAVAILABLE` once otherwise).  Layers (M3-19c): a second animator on a descendant is a layer over the first — animators apply ancestor-first, so the deeper one owns the entities its clip names (a mask by placement: an `Animator` on the spine drives the upper body over the one on the root). `weight` blends its pose over what is under it (`0` leaves it untouched), `additive` adds the clip's difference from its first frame instead of replacing the pose (a wave over a walk). `root_motion` takes the planar translation and yaw of the clip's root channel out of the pose and publishes the per-tick delta: a `CharacterController` on the entity walks by it, else the entity's own transform moves.  ADR-0032: with a `controller` (an Animator Controller, `.controller.json`) the animator runs its state machine instead and `clip` and `looping` are not used; `speed`, `playing`, `weight` and `root_motion` still apply to the whole animator.
///
/// `fynkel.Animator` (component, id 21, 64 bytes).
class Animator implements WireRecord {
  const Animator({
    this.clip = AssetRef.none,
    this.speed = 1.0,
    this.looping = true,
    this.playing = true,
    this.weight = 1.0,
    this.additive = false,
    this.rootMotion = false,
    this.controller,
  });

  /// The clip (an imported glTF `anim/<a>` sub-asset or a blend space `.blend.json`); nil plays nothing.
  final AssetRef clip;
  /// Playback rate, `1` is authored speed; finite.
  final double speed;
  final bool looping;
  final bool playing;
  /// Blend weight of this animator's pose over the pose beneath it, in `[0, 1]`; `1` (the default) replaces it.
  final double weight;
  /// Add the clip's delta from its first frame instead of replacing.
  final bool additive;
  /// Extract the root channel's planar motion (see above).
  final bool rootMotion;
  /// The Animator Controller it runs (ADR-0032); none plays `clip`.
  final AssetRef? controller;

  static const String schemaName = 'fynkel.Animator';
  static const int wireSize = 64;
  static const int componentId = 21;

  /// Writes [wireSize] bytes at [offset]; strings go to [strings].
  @override
  void encode(ByteData d, int offset, WireStrings strings) {
    writeAssetRef(d, offset + 0, clip, strings);
    d.setFloat32(offset + 24, speed, Endian.little);
    d.setUint8(offset + 28, looping ? 1 : 0);
    d.setUint8(offset + 29, playing ? 1 : 0);
    d.setFloat32(offset + 32, weight, Endian.little);
    d.setUint8(offset + 36, additive ? 1 : 0);
    d.setUint8(offset + 37, rootMotion ? 1 : 0);
    writeOptionalAssetRef(d, offset + 40, controller, strings);
  }

  /// Reads [wireSize] bytes at [offset]; [tail] resolves strings.
  static Animator decode(ByteData d, int offset, Uint8List tail) {
    return Animator(
      clip: readAssetRef(d, offset + 0, tail),
      speed: d.getFloat32(offset + 24, Endian.little),
      looping: d.getUint8(offset + 28) != 0,
      playing: d.getUint8(offset + 29) != 0,
      weight: d.getFloat32(offset + 32, Endian.little),
      additive: d.getUint8(offset + 36) != 0,
      rootMotion: d.getUint8(offset + 37) != 0,
      controller: readOptionalAssetRef(d, offset + 40, tail),
    );
  }

  /// This value with the given fields replaced.
  Animator copyWith({
    AssetRef? clip,
    double? speed,
    bool? looping,
    bool? playing,
    double? weight,
    bool? additive,
    bool? rootMotion,
    AssetRef? controller,
  }) =>
      Animator(
        clip: clip ?? this.clip,
        speed: speed ?? this.speed,
        looping: looping ?? this.looping,
        playing: playing ?? this.playing,
        weight: weight ?? this.weight,
        additive: additive ?? this.additive,
        rootMotion: rootMotion ?? this.rootMotion,
        controller: controller ?? this.controller,
      );

  /// The document form: a component's `data` in a scene or prefab (the
  /// schema's field names, `f32`s at their shortest, enums by name).
  Map<String, Object?> toJson() => {
        'clip': docAssetRef(clip),
        'speed': docFloat(speed),
        'looping': looping,
        'playing': playing,
        'weight': docFloat(weight),
        'additive': additive,
        'root_motion': rootMotion,
        if (controller != null) 'controller': docAssetRef(controller!),
      };

  @override
  bool operator ==(Object other) =>
      other is Animator && other.clip == clip && other.speed == speed && other.looping == looping && other.playing == playing && other.weight == weight && other.additive == additive && other.rootMotion == rootMotion && other.controller == controller;

  @override
  int get hashCode => Object.hashAll([clip, speed, looping, playing, weight, additive, rootMotion, controller]);

  @override
  String toString() => 'Animator(clip: $clip, speed: $speed, looping: $looping, playing: $playing, weight: $weight, additive: $additive, rootMotion: $rootMotion, controller: $controller)';
}

