  /// The skin sub-asset.
  final AssetRef skin;
  /// Name of the skeleton root entity; empty for the tree root.
  final String skeleton;

  static const String schemaName = 'fynkel.Skin';
  static const int wireSize = 32;
  static const int componentId = 22;

  /// Writes [wireSize] bytes at [offset]; strings go to [strings].
  @override
  void encode(ByteData d, int offset, WireStrings strings) {
    writeAssetRef(d, offset + 0, skin, strings);
    writeWireString(d, offset + 24, skeleton, strings);
  }

  /// Reads [wireSize] bytes at [offset]; [tail] resolves strings.
  static Skin decode(ByteData d, int offset, Uint8List tail) {
    return Skin(
      skin: readAssetRef(d, offset + 0, tail),
      skeleton: readWireString(d, offset + 24, tail),
    );
  }

  /// This value with the given fields replaced.
  Skin copyWith({
    AssetRef? skin,
    String? skeleton,
  }) =>
      Skin(
        skin: skin ?? this.skin,
        skeleton: skeleton ?? this.skeleton,
      );

  /// The document form: a component's `data` in a scene or prefab (the
  /// schema's field names, `f32`s at their shortest, enums by name).
  Map<String, Object?> toJson() => {
        'skin': docAssetRef(skin),
        'skeleton': skeleton,
      };

  @override
  bool operator ==(Object other) =>
      other is Skin && other.skin == skin && other.skeleton == skeleton;

  @override
  int get hashCode => Object.hashAll([skin, skeleton]);

  @override
  String toString() => 'Skin(skin: $skin, skeleton: $skeleton)';
}

/// Drives a `fynkel.Animator` (M3-19; simulation lane only). Rejected at the tick with `MISSING_COMPONENT` (no animator) or `INVALID_PAYLOAD` (non-finite value, negative fade, a weight outside `[0, 1]`, an empty parameter name; ADR-0032: a clip op on an animator that runs a controller, a controller op on one that does not, a parameter or state the controller does not have, a value of another type).
///
/// `fynkel.cmd.Animate` (command, id 9, 72 bytes).
class AnimateCommandRecord implements WireRecord {
  const AnimateCommandRecord({
    required this.entity,
    required this.op,
    required this.seconds,
    required this.speed,
    required this.looping,
    required this.clip,
    required this.value,
    required this.name,
    required this.integer,
    required this.layer,
  });

  final int entity;
  final AnimateOp op;
  /// Fade length for `crossfade`, the target time for `setTime`.
  final double seconds;
  /// Playback rate for `play`/`crossfade`/`setSpeed`.
  final double speed;
  /// For `play`/`crossfade`.
  final bool looping;
  /// For `play`/`crossfade`.
  final AssetRef clip;
  /// The weight for `setWeight`, the parameter value for `setParameter`/`setFloat`/`setBool`, the start fraction for `playState`/`crossFadeState`, the blend out for `playOneShot`/`stopOneShot`.
  final double value;
  /// The parameter name for `setParameter` and the typed setters, the state name for `playState`/`crossFadeState`, the slot for `playOneShot`/`stopOneShot`.
  final String name;
  /// The value for `setInteger` (ADR-0032).
  final int integer;
  /// The layer for `playState`/`crossFadeState`; `-1` is the first layer with a state of that name.
  final int layer;

  static const String schemaName = 'fynkel.cmd.Animate';
  static const int wireSize = 72;
  static const int commandKind = 9;

  /// Writes [wireSize] bytes at [offset]; strings go to [strings].
  @override
  void encode(ByteData d, int offset, WireStrings strings) {
    d.setUint64(offset + 0, entity, Endian.little);
    d.setUint32(offset + 8, op.index, Endian.little);
    d.setFloat32(offset + 12, seconds, Endian.little);
    d.setFloat32(offset + 16, speed, Endian.little);
    d.setUint8(offset + 20, looping ? 1 : 0);
    writeAssetRef(d, offset + 24, clip, strings);
    d.setFloat32(offset + 48, value, Endian.little);
    writeWireString(d, offset + 52, name, strings);
    d.setInt32(offset + 60, integer, Endian.little);
    d.setInt32(offset + 64, layer, Endian.little);
  }

  /// Reads [wireSize] bytes at [offset]; [tail] resolves strings.
  static AnimateCommandRecord decode(ByteData d, int offset, Uint8List tail) {
    return AnimateCommandRecord(
      entity: d.getUint64(offset + 0, Endian.little),
