    d.setUint64(offset + 0, entity, Endian.little);
    writeWireString(d, offset + 8, name, strings);
    d.setUint32(offset + 16, kind.index, Endian.little);
    d.setFloat32(offset + 20, value, Endian.little);
    d.setInt32(offset + 24, integer, Endian.little);
    d.setUint8(offset + 28, flag ? 1 : 0);
  }

  /// Reads [wireSize] bytes at [offset]; [tail] resolves strings.
  static AnimatorParameterRecord decode(ByteData d, int offset, Uint8List tail) {
    return AnimatorParameterRecord(
      entity: d.getUint64(offset + 0, Endian.little),
      name: readWireString(d, offset + 8, tail),
      kind: enumValue(AnimatorParameterKind.values, d.getUint32(offset + 16, Endian.little), 'fynkel.AnimatorParameterKind'),
      value: d.getFloat32(offset + 20, Endian.little),
      integer: d.getInt32(offset + 24, Endian.little),
      flag: d.getUint8(offset + 28) != 0,
    );
  }

  /// The document form: a component's `data` in a scene or prefab (the
  /// schema's field names, `f32`s at their shortest, enums by name).
  Map<String, Object?> toJson() => {
        'entity': entity,
        'name': name,
        'kind': kind.name,
        'value': docFloat(value),
        'integer': integer,
        'flag': flag,
      };

  @override
  bool operator ==(Object other) =>
      other is AnimatorParameterRecord && other.entity == entity && other.name == name && other.kind == kind && other.value == value && other.integer == integer && other.flag == flag;

  @override
  int get hashCode => Object.hashAll([entity, name, kind, value, integer, flag]);

  @override
  String toString() => 'AnimatorParameterRecord(entity: $entity, name: $name, kind: $kind, value: $value, integer: $integer, flag: $flag)';
}

/// How the world reads one native component off the wire.
class ComponentCodec {
  const ComponentCodec(this.id, this.name, this.type, this.wireSize, this.decode);

  /// `ComponentId`.
  final int id;
  final String name;
  final Type type;
  final int wireSize;
  final WireRecord Function(ByteData d, int offset, Uint8List tail) decode;
}

